-- 0038_admin_division.sql - 行政区划，全球五级，一张表。
--
-- GENERATED by scripts/data/build-admin-division.mjs. Do not hand-edit: the
-- seed is 7 continent, 250 country, 34 province, 342 city, 2978 county, derived from two published datasets pinned by version and
-- integrity hash (the sources are named in the generator). Re-run the generator
-- to change it.
--
-- WHY A TABLE AND NOT A CONSTANT (owner, 2026-09-08, superseding ADR-026 D1's
-- "keep it in the build until"). The trigger it named has arrived: the product
-- needs the levels below province. 2,978 counties cannot be a TypeScript array
-- - they are looked up, filtered and joined, which is what a table is for, and
-- unlike the 34 provinces nothing in the code branches on them.
--
-- GLOBAL, NOT PER WORKSPACE. Which provinces China has is not a tenant's
-- decision, so this table has no workspace_id: one row set, read by everyone.
-- What IS a tenant's decision is how they carve their market, and that already
-- has its own per-workspace tables (market_division, 0036) which reference
-- these names.
--
-- ITS OWN SCHEMA, yucer_ref. The seven product schemas hold rows a workspace
-- owns; a table with no workspace_id sitting among them would read as one
-- somebody forgot to scope. `ref` says what it is: reference data, seeded by
-- DDL, read-only to the service role.
--
-- FIVE LEVELS, ONE SELF-REFERENCING TABLE: 1 continent, 2 country, 3 province,
-- 4 city, 5 county. One table rather than five because the depth is not the
-- same everywhere - the SARs stop at province level, and a country outside
-- China has no rows below it yet - and five tables would encode a shape that
-- is only true of one country.
--
-- CODES. Level 1 and 2 use the ISO alpha-2 letters (AS/EU/..., CN/US/...);
-- levels 3 to 5 use GB/T 2260's six-digit codes (110000 / 110100 / 110101).
-- They collide across levels - NA is both North America and Namibia - so the
-- natural key is (level, code), not code alone, and the parent link is by id.
--
-- Idempotent: every insert is ON CONFLICT (level, code) DO NOTHING, and a row
-- whose parent is missing is skipped rather than orphaned.

CREATE SCHEMA IF NOT EXISTS yucer_ref;

CREATE TABLE IF NOT EXISTS yucer_ref.admin_division (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  level       SMALLINT NOT NULL,
  -- The canonical key AT THIS LEVEL: ISO alpha-2 for a continent or country,
  -- GB/T 2260's six digits for a province, city or county.
  code        VARCHAR(12) NOT NULL,
  -- 两字母英文简称: AS / CN / GD. Null below province - counties have no
  -- standard letters, and inventing some would be a second vocabulary for
  -- places that already have one.
  abbr_en     VARCHAR(8),
  -- 中文全称 - 中华人民共和国 / 广东省 / 深圳市 / 福田区.
  name_zh     VARCHAR(128) NOT NULL,
  -- 中文简称 - 中国 / 广东 / 深圳 / 福田. EQUAL TO name_zh where no safe rule
  -- applies: 恩施土家族苗族自治州 has no short form anybody says, and cutting
  -- the ethnic qualifier off would produce a name rather than shorten one.
  short_zh    VARCHAR(64) NOT NULL,
  -- 英文全称 - Asia / People's Republic of China / Guangdong. Null below
  -- province: romanising 2,978 county names is a generation step with its own
  -- failure mode (重庆 is Chongqing, not Zhongqing), and a wrong romanisation
  -- of a place name is fabricated data.
  name_en     VARCHAR(128),
  parent_id   UUID REFERENCES yucer_ref.admin_division (id) ON DELETE RESTRICT,
  -- The materialised path of CODES, root first: 'AS/CN/440000/440300/440304'.
  -- "Everything under Guangdong" is then one indexed prefix scan instead of a
  -- recursive CTE, which is the query this tree exists to answer.
  path        VARCHAR(64) NOT NULL,
  -- Divisions are abolished and merged (巢湖市, 2011). A row that records where
  -- something happened cannot be deleted when the place stops existing, so it
  -- is retired instead and every historical reference still resolves.
  status      VARCHAR(16) NOT NULL DEFAULT 'active',
  -- WHICH DATASET PUT THIS ROW HERE. The table is three sources at once - the
  -- Chinese divisions, the ISO country list, and three hand-seeded SARs - and
  -- a refresh has to be able to tell them apart.
  source      VARCHAR(64) NOT NULL,
  sort_order  INTEGER NOT NULL DEFAULT 0,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_admin_division_level CHECK (level BETWEEN 1 AND 5),
  CONSTRAINT chk_admin_division_status CHECK (status IN ('active', 'retired')),
  -- A continent has no parent; everything else must have one. Stated as a
  -- constraint rather than trusted to the seed: an orphaned county is a row
  -- that exists and can never be reached by walking down.
  CONSTRAINT chk_admin_division_root CHECK ((level = 1) = (parent_id IS NULL)),
  CONSTRAINT uidx_admin_division_code UNIQUE (level, code)
);

CREATE INDEX IF NOT EXISTS idx_admin_division_parent
  ON yucer_ref.admin_division (parent_id, sort_order);
CREATE INDEX IF NOT EXISTS idx_admin_division_level
  ON yucer_ref.admin_division (level, sort_order);
-- text_pattern_ops, not the default: a btree on a text column supports
-- `LIKE 'AS/CN/440000/%'` only under this operator class.
CREATE INDEX IF NOT EXISTS idx_admin_division_path
  ON yucer_ref.admin_division (path text_pattern_ops);


-- --- level 1: continent (7) -------------------------------------
INSERT INTO yucer_ref.admin_division
  (level, code, abbr_en, name_zh, short_zh, name_en, path, source, sort_order, parent_id)
SELECT v.level, v.code, v.abbr_en, v.name_zh, v.short_zh, v.name_en, v.path, v.source,
       v.sort_order, p.id
  FROM (VALUES
    (1, 'AS', 'AS', '亚洲', '亚洲', 'Asia', 'AS', 'world-countries@5.1.0', 1, NULL),
    (1, 'EU', 'EU', '欧洲', '欧洲', 'Europe', 'EU', 'world-countries@5.1.0', 2, NULL),
    (1, 'AF', 'AF', '非洲', '非洲', 'Africa', 'AF', 'world-countries@5.1.0', 3, NULL),
    (1, 'NA', 'NA', '北美洲', '北美洲', 'North America', 'NA', 'world-countries@5.1.0', 4, NULL),
    (1, 'SA', 'SA', '南美洲', '南美洲', 'South America', 'SA', 'world-countries@5.1.0', 5, NULL),
    (1, 'OC', 'OC', '大洋洲', '大洋洲', 'Oceania', 'OC', 'world-countries@5.1.0', 6, NULL),
    (1, 'AN', 'AN', '南极洲', '南极洲', 'Antarctica', 'AN', 'world-countries@5.1.0', 7, NULL)
  ) AS v(level, code, abbr_en, name_zh, short_zh, name_en, path,
        source, sort_order, parent_code)
  LEFT JOIN yucer_ref.admin_division p
    ON p.level = v.level - 1 AND p.code = v.parent_code
 WHERE v.parent_code IS NULL OR p.id IS NOT NULL
ON CONFLICT (level, code) DO NOTHING;

