  LEFT JOIN yucer_ref.admin_division p
    ON p.level = v.level - 1 AND p.code = v.parent_code
 WHERE v.parent_code IS NULL OR p.id IS NOT NULL
ON CONFLICT (level, code) DO NOTHING;
